import manifest from '../imageManifest.json'

// Optimized images live in /img as <slug>.webp (largest, <=1600px) plus <slug>-480.webp / <slug>-960.webp.
// Generated by scripts/optimize-images.mjs — see CLAUDE.md "Images".

const variant = (src, w) => src.replace(/\.webp$/, `-${w}.webp`)

/** srcset string for an optimized image, or undefined for anything not in the manifest. */
export function srcSet(src) {
  const m = manifest[src]
  if (!m) return undefined
  return m.widths.map((w) => `${w === m.w ? src : variant(src, w)} ${w}w`).join(', ')
}

/** Single best-fit URL for a target pixel width (for CSS backgrounds, SVG <image>, WebGL textures). */
export function pick(src, px) {
  const m = manifest[src]
  if (!m) return src
  const w = m.widths.find((x) => x >= px) ?? m.w
  return w === m.w ? src : variant(src, w)
}

/**
 * Props to spread on an <img>: responsive srcset/sizes, intrinsic width/height (reserves space, no layout shift),
 * lazy by default. Above-the-fold images: { eager: true }, and the LCP candidate: { priority: true }.
 */
export function imgProps(src, sizes, { eager = false, priority = false } = {}) {
  const m = manifest[src]
  return {
    src,
    srcSet: srcSet(src),
    sizes: m ? sizes : undefined,
    width: m?.w,
    height: m?.h,
    loading: eager || priority ? 'eager' : 'lazy',
    decoding: 'async',
    ...(priority ? { fetchPriority: 'high' } : {}),
  }
}
